const fs = require('fs');
const plan = JSON.parse(fs.readFileSync('.exp_agent/round_01/plan.json', 'utf8'));
const out = {
  selected_rules: plan.rules.map(r => r.rule),
  entity_repairs: [],
  blocked: [],
  unresolved_external: []
};
for (const rule of plan.rules) {
  for (const file of rule.files) {
    const lines = fs.readFileSync(file.relative_path, 'utf8').split(/\\r?\\n/);
    let entities;
    let transformation;
    if (rule.rule.endsWith('avoid-empty-callback')) {
      entities = ['Index.build Button onClick listener'];
      transformation = 'Removed the empty onClick listener from the Button while retaining the Button and its existing visual properties.';
    } else if (rule.rule.endsWith('no-state-var-access-in-loop')) {
      entities = ['update() state text accumulator'];
      transformation = 'Copied this.text to a local accumulator before the loop, appended to the local value inside the loop, and assigned the accumulated result back once after the loop.';
    } else if (rule.rule.endsWith('remove-container-without-property')) {
      entities = file.locations.map(loc => 'Column container at planned location ' + loc.line + ':' + loc.column);
      transformation = 'Removed each listed property-less single-child Column wrapper and retained its existing child content and surrounding NavDestination structure.';
    } else if (rule.rule.endsWith('remove-redundant-state-var') || rule.rule.endsWith('remove-unchanged-state-var')) {
      entities = file.locations.map(loc => {
        const line = lines[loc.line - 1] || '';
        const match = line.match(/(?:@State\\s+)?([A-Za-z_"'$][A-Za-z0-9_$]*)'"\\s*:/);
        return match ? 'state field ' + match[1] : 'state field declaration at planned location ' + loc.line + ':' + loc.column;
      });
      transformation = 'Removed the @State decorator from the listed field declarations, preserving each field name, type, initializer, declaration, and access behavior.';
    } else {
      entities = ['planned entity'];
      transformation = 'Applied the behavior-preserving repair for the listed entity.';
    }
    out.entity_repairs.push({
      rule: rule.rule,
      relative_path: file.relative_path,
      locations: file.locations,
      entities,
      evidence: file.locations.map(loc => 'Repository evidence: ' + file.relative_path + ':' + loc.line + ':' + loc.column + ' contains the planned affected entity and its surrounding implementation was inspected.'),
      transformation,
      status: 'repaired'
    });
  }
}
process.stdout.write(JSON.stringify(out, null, 2) + '\\\\n');
